-- SEC-070 — suporte a geofence de polígono livre para futura edição pelo Security Map.
CREATE OR REPLACE FUNCTION update_asset_geofence(p_asset_id uuid,p_geofence_geojson text,p_enabled boolean DEFAULT true) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,auth AS $$ DECLARE v_org uuid;v_prop uuid;v_geofence geometry(Polygon,4326);BEGIN SELECT organization_id,property_id INTO v_org,v_prop FROM assets WHERE id=p_asset_id;IF NOT FOUND THEN RAISE EXCEPTION 'asset_not_found';END IF;IF v_prop IS NULL OR NOT app_can_manage_property(v_prop) THEN RAISE EXCEPTION 'asset_management_required';END IF;IF p_enabled THEN IF COALESCE(btrim(p_geofence_geojson),'')='' THEN RAISE EXCEPTION 'geofence_required';END IF;BEGIN v_geofence:=ST_SetSRID(ST_GeomFromGeoJSON(p_geofence_geojson),4326)::geometry(Polygon,4326);EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'invalid_geofence';END;IF NOT ST_IsValid(v_geofence) OR ST_IsEmpty(v_geofence) THEN RAISE EXCEPTION 'invalid_geofence';END IF;UPDATE assets SET geofence=v_geofence,geofence_enabled=true,geofence_state='unknown',updated_at=now() WHERE id=p_asset_id;ELSE UPDATE assets SET geofence_enabled=false,geofence_state='unknown',updated_at=now() WHERE id=p_asset_id;END IF;INSERT INTO audit_logs(organization_id,actor_user_id,action,entity_type,entity_id,details) VALUES(v_org,app_current_user_id(),'asset.geofence_updated','asset',p_asset_id,jsonb_build_object('enabled',p_enabled));RETURN true;END $$;
GRANT EXECUTE ON FUNCTION update_asset_geofence(uuid,text,boolean) TO authenticated;
